// Verbatim port of monster_detail.html inline script wrapped for the SPA — regenerated by
// scripts/wrap_p5_js.py; edit the generator, not this file.
import { exposeGlobals, unexposeGlobals } from '../../../lib/legacy.js';

export function init(ctx, d, G) {
  let _dead = false;
  void d;
  const MD_NAME = G.MD_NAME;
  const MD_INSTANCE = G.MD_INSTANCE;
  const MD_HP_MAX = G.MD_HP_MAX;

  const GAME_INFO = G.GAME_INFO;   // game system the rollers follow
  DiceCore.setSystem(GAME_INFO);
  let _mdSysPanel = null;   // mounted after the die/mode helpers exist (below)

  // ── Die / mode selection (same behavior as the sheet & map rollers) ─────────
  let _mdSides = 20;
  let _mdAdv   = 'normal';

  function mdSelectDie(s) {
    _mdSides = s;
    document.querySelectorAll('.md-die-btn').forEach(b => {
      const on = parseInt(b.dataset.sides) === s;
      b.classList.toggle('active', on);
      if (on) {
        b.style.setProperty('background',   'var(--ttrpg-accent)', 'important');
        b.style.setProperty('border-color', 'var(--ttrpg-accent)', 'important');
        b.style.setProperty('color',        'var(--sp-on-accent)', 'important');
      } else {
        b.style.removeProperty('background');
        b.style.removeProperty('border-color');
        b.style.removeProperty('color');
      }
    });
    mdSetAdvMode(_mdAdv);   // re-evaluate: adv/dis only applies to d20
  }

  function mdStepCount(delta) {
    const el = document.getElementById('md-count');
    el.value = Math.min(20, Math.max(1, (parseInt(el.value) || 1) + delta));
  }

  function mdSetMod(v) {
    document.getElementById('md-mod').value = v;
  }

  function mdSetAdvMode(mode) {
    if (_mdSides !== 20) mode = 'normal';   // adv/dis is a d20 concept
    _mdAdv = mode;
    const cfg = {
      'md-adv-normal': { mode: 'normal',       bg: 'var(--ttrpg-accent)', fg: 'var(--sp-on-accent)' },
      'md-adv-adv':    { mode: 'advantage',    bg: '#28a745',             fg: '#ffffff' },
      'md-adv-dis':    { mode: 'disadvantage', bg: '#dc3545',             fg: '#ffffff' },
    };
    Object.entries(cfg).forEach(([id, c]) => {
      const el = document.getElementById(id);
      if (!el) return;
      const on = _mdAdv === c.mode;
      el.classList.toggle('active', on);
      if (on) {
        el.style.setProperty('background',   c.bg, 'important');
        el.style.setProperty('border-color', c.bg, 'important');
        el.style.setProperty('color',        c.fg, 'important');
      } else {
        el.style.removeProperty('background');
        el.style.removeProperty('border-color');
        el.style.removeProperty('color');
      }
    });
  }

  function mdReset() {
    document.getElementById('md-count').value = 1;
    document.getElementById('md-mod').value = 0;
    document.getElementById('md-label').value = '';
    document.getElementById('md-result').style.display = 'none';
    mdSelectDie(20);
    mdSetAdvMode('normal');
    if (_mdSysPanel) _mdSysPanel.reset();
  }

  mdSelectDie(20);
  mdSetAdvMode('normal');
  _mdSysPanel = DiceCore.mountSystemPanel(document.getElementById('md-system-panel'), {
    btnClass: 'btn btn-sm btn-outline-secondary',
    quickContainer: document.getElementById('md-quicklabels'),
    labelInput: document.getElementById('md-label'),
    setDie: mdSelectDie,
    setCount: n => { document.getElementById('md-count').value = n; },
    getCount: () => parseInt(document.getElementById('md-count').value) || 1,
    setMod: mdSetMod,
    setAdv: mdSetAdvMode,
  });
  ctx.every(10000, () => {   // Floor / system changes made on the session page
    fetch('/ttrpg/dice/system').then(r => r.json()).then(g => _mdSysPanel.refresh(g)).catch(() => {});
  });

  function mcAdjust(sign) {
    if (MD_INSTANCE === null) return;
    const amt = Math.max(1, parseInt(document.getElementById('mc-amt').value) || 1);
    fetch(`/ttrpg/monsters/instance/${MD_INSTANCE}/hp`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ delta: sign * amt }),
    }).then(r => r.json()).then(d => {
      if (!d.ok) return;
      document.getElementById('mc-hp-num').textContent =
        `HP ${d.hp_current} / ${MD_HP_MAX}`;
      const fill = document.getElementById('mc-hp-fill');
      fill.style.width = d.hp_pct + '%';
      fill.style.background = d.hp_pct > 50 ? '#28a745'
                            : d.hp_pct > 25 ? '#ffc107' : '#dc3545';
      document.getElementById('mc-note').textContent =
        d.hp_current <= 0 ? '☠ down' : '';
    });
  }

  function mdRoll() {
    const btn = event.target;
    btn.disabled = true;
    fetch('/ttrpg/dice/roll', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        character_id: null,
        char_name: MD_NAME,
        count:    parseInt(document.getElementById('md-count').value) || 1,
        sides:    _mdSides,
        modifier: parseInt(document.getElementById('md-mod').value) || 0,
        label:    document.getElementById('md-label').value.trim(),
        adv_mode: _mdAdv,
        ...(_mdSysPanel ? _mdSysPanel.getContext() : {}),
      }),
    }).then(r => r.json()).then(d => {
      btn.disabled = false;
      if (!d.ok) return;
      const out = document.getElementById('md-result');
      out.style.display = '';
      out.style.color = 'var(--ttrpg-accent)';
      const mode = d.adv_mode !== 'normal' ? ` [${d.adv_mode}]` : '';
      out.textContent = `${d.expression}${mode}${d.label ? ' ' + d.label : ''} → ${d.total}`;
      if (d.outcome && d.outcome.ok === false) out.style.color = '#dc3545';
    }).catch(() => { btn.disabled = false; });
  }

  const NAMES = ["mdSelectDie", "mdStepCount", "mdSetMod", "mdSetAdvMode", "mdReset", "mcAdjust", "mdRoll"];
  exposeGlobals({ mdSelectDie, mdStepCount, mdSetMod, mdSetAdvMode, mdReset, mcAdjust, mdRoll });
  return () => {
    _dead = true;

    unexposeGlobals(NAMES);
  };
}
